/**
 * Illustrations for cards and pack fronts, in `public/soul/art/<key>.webp`: public-domain / free-licensed images
 * from Wikimedia Commons (`ART`, credited) and pictures drawn for the game (`DRAWN_ART`, generated by
 * `npm run soul-art` from the SVG scenes in `scripts/soul-art/`).
 */
export interface ArtCredit {
  title: string;
  author: string;
  license: string;
  url: string;
  /** Vertical focus of the crop, 0 = top, 1 = bottom (faces are usually near the top). */
  focus?: number;
}

